import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"27、【頤】 震下艮上","description":"周易闡真 - 27、【頤】 震下艮上","frontmatter":{"title":"27、【頤】 震下艮上","description":"周易闡真 - 27、【頤】 震下艮上"},"headers":[],"relativePath":"classics/chanzhen/028.md","filePath":"classics/chanzhen/028.md"}'),s={name:"classics/chanzhen/028.md"};function n(c,a,i,o,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：頤，貞吉，養正則吉也。觀頤，觀其所養也。自求口實，觀其自養也。天地養萬物，聖人養賢以及萬民，頤之時大矣哉！</p></blockquote><h1 id="_27、【頤】-震下艮上" tabindex="-1">27、【頤】 震下艮上 <a class="header-anchor" href="#_27、【頤】-震下艮上" aria-label="Permalink to “27、【頤】 震下艮上”">​</a></h1><p>初九：舍爾靈龜，觀我朵頤，兇。</p><p>六二：顛頤，拂經於丘頤，徵兇。</p><p>六三：拂頤，貞兇，十年勿用，無攸利。</p><p>六四：顛頤，吉。虎視眈眈，其欲逐逐，無咎。</p><p>六五：拂經，居貞吉，不可涉大川。</p><p>上九：由頤，厲吉，利涉大川。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：山下有雷，頤。君子以慎言語，節飲食。</p><p>頤者，腮頤，取養之義。上艮山，下震雷，是山下有雷也。山本靜，雷本動，以靜養動，動本於靜，如口上靜下動，靜以待動，頤養之象也。</p><p>君子有見於此，知口為出納之官，是非之門，禍福之根，以是慎言語、節飲食也。言語者，心之聲。言語正，則心正；言語邪，則心邪。一言一語必有益於世道人心而後出，不敢妄發，言語必謹。飲食者，身所貴。飲食當，則益身；飲食不當，則傷身。一飲一食，必須察其來由可否而後用，不敢過食，飲食必節。謹言語，則心有養矣；節飲食，則身有養矣。身心俱得其養，內外無傷，性命可修。所謂食其時，百骸理，動其機，萬化安也。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>頤，音夷。舍，音捨。朵，多果反。眈，音丹。</p><p>頤者，腮頷。凡口食物則動，取其有養人之義。卦德上艮止，下震動。動不離止，止以養動，動不妄動，止不空止，動止如一，故謂頤。此擇善固執，虛以求實之卦，承上無妄而來。無妄者，動而健行，若非有涵養之功，則動之健之，皆不得當。無妄而即有妄，此養之道所由貴。養者，養其正，而去其不正也。正則有益於身心，不正則有害於身心，是以頤之道必貞，而始能得吉。</p><p>然欲養之正，必先觀其養道之真假。觀非眼觀之謂，乃心中辨別是非，以窮理也。理明則真知灼見，動而修正，靜而養正，動靜皆得其所養，可以自求口實矣。不曰求口食，而曰求口實，不曰求口實，而曰自求口實，是所求者正，所實者大，不在膏粱厚味，而在仁義道德。然其所以飽仁義而味道德，總在自求，而不由人，一日克己復禮，天下歸仁焉。</p><p>自求口實，則得實，是在自求何如耳。口者，虛中之物。實者，充實之謂。虛其心，實其腹，虛實相應，時動則動，動而進陽；時靜則靜，靜而運陰，動以修外，靜以養內，動靜不拘，內外合道。止固養，動亦養，動止皆不失其正，終得完成大道，以吉全之矣。</p><p>彼一切以飢渴之害為心害者，養其小而失其大，謂之自求口食則可，謂之自求口實，則失之遠矣。既失其實，何得謂養乎?</p><p>初九，剛而妄動，不養於內，求養於外，棄真認假，如舍爾靈龜，觀我朵頤矣。此養口失實、不謹於始之養也。</p><p>六二，以無德而欲養有德，自高自大，無而為有，虛而為盈，是顛倒其養，拂其借剛養柔之經，常於丘頤矣。此愚而自用、不知求實之養也。</p><p>六三，居於動極，順其所欲，只在衣食上打點，不在性命上留心，養其小體為小人，是拂其養實之頤，即口食得正，亦是兇道。如此之人，雖終身而不知有德可修，豈僅十年勿用，無攸利乎?此愚而無知、終於不實之養也。</p><p>六四，有應於陽，以尊屈卑，不恥下問，借他人之剛明，以破己之柔暗，是謂顛頤。但以尊屈卑，恐有挾貴而問，其心不誠之嫌。幸其柔而得正，如虎視眈眈，其欲逐逐，目專一而心真切，出於自然，絕無勉強，未取於人，先求其己，求實即得實，始而有咎者，終可無咎。此不實求實、以上求下之養也。</p><p>六五，虛心自處，只知養內，不知養外，是拂其養實之常經矣。然雖不能養實，而能養虛，居於貞而不遷移，亦致吉之道。但不可涉大川，以成金丹有為之功。此虛而不實、孤寂守靜之養也。</p><p>上九，剛居於柔，止於其所，動靜如一，既能養內，又能養外，既能養己，又能養人。其所養者大，乃養道所由，得以全始全終者，是謂由頤。然全始全終之養，須要在危厲之處做出，方能得吉，故又利涉於大川。大川至險之地，逆境也。逆境能養，則順境能養，自不待言。養而至於逆順不拘，險易無礙，則氣質俱化，陰陽混合，止於至善而不遷，聖胎凝結，大道完成矣。此虛實兼該、有始有終之養也。</p><p>六爻各有所養，邪正不同，是非不等。求其剛柔相當，逆順不拘，有為無為，全始全終者，其惟上九之一爻乎?修道者急須靜觀密察，以虛求實，養其正而歸於至善無惡之地而後可。</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
